#[derive(Clone)]
struct ResidentNamedZoneInterval {
    start_seconds: i64,
    end_seconds: i64,
    offset_seconds: i32,
}

#[derive(Clone)]
struct ResidentNamedZoneRules {
    canonical_name: String,
    intervals: Vec<ResidentNamedZoneInterval>,
}

fn named_zone_range() -> Result<(i64, i64)> {
    let timestamp = |year, month, day| {
        chrono::NaiveDate::from_ymd_opt(year, month, day)
            .and_then(|date| date.and_hms_opt(0, 0, 0))
            .map(|date| date.and_utc().timestamp())
            .ok_or_else(|| Error::internal("resident IANA range date is invalid"))
    };
    Ok((timestamp(1800, 1, 1)?, timestamp(2201, 1, 1)?))
}

fn named_zone_offset_at(zone: chrono_tz::Tz, seconds: i64) -> Result<i32> {
    let utc = chrono::DateTime::<chrono::Utc>::from_timestamp(seconds, 0).ok_or_else(|| {
        Error::new(
            ErrorCode::TemporalRange,
            "resident IANA transition timestamp is outside chrono range",
        )
    })?;
    Ok(zone
        .offset_from_utc_datetime(&utc.naive_utc())
        .fix()
        .local_minus_utc())
}

fn build_named_zone_rules(name: &str) -> Result<Option<ResidentNamedZoneRules>> {
    let Ok(zone) = name.parse::<chrono_tz::Tz>() else {
        return Ok(None);
    };
    let (range_start, range_end) = named_zone_range()?;
    let mut intervals = Vec::new();
    let mut interval_start = range_start;
    let mut current_offset = named_zone_offset_at(zone, range_start)?;
    let mut probe = range_start + 86_400;
    while probe < range_end {
        let offset = named_zone_offset_at(zone, probe)?;
        if offset != current_offset {
            let mut low = probe - 86_400;
            let mut high = probe;
            while high - low > 1 {
                let middle = low + (high - low) / 2;
                if named_zone_offset_at(zone, middle)? == current_offset {
                    low = middle;
                } else {
                    high = middle;
                }
            }
            intervals.push(ResidentNamedZoneInterval {
                start_seconds: interval_start,
                end_seconds: high,
                offset_seconds: current_offset,
            });
            interval_start = high;
            current_offset = named_zone_offset_at(zone, high)?;
        }
        probe = probe
            .checked_add(86_400)
            .ok_or_else(|| Error::internal("resident IANA transition probe overflow"))?;
    }
    intervals.push(ResidentNamedZoneInterval {
        start_seconds: interval_start,
        end_seconds: range_end,
        offset_seconds: current_offset,
    });
    Ok(Some(ResidentNamedZoneRules {
        canonical_name: zone.name().to_owned(),
        intervals,
    }))
}

fn cached_named_zone_rules(name: &str) -> Result<Option<ResidentNamedZoneRules>> {
    static RULES: OnceLock<Mutex<BTreeMap<String, ResidentNamedZoneRules>>> = OnceLock::new();
    let mut rules = match RULES.get_or_init(|| Mutex::new(BTreeMap::new())).lock() {
        Ok(rules) => rules,
        Err(poisoned) => poisoned.into_inner(),
    };
    if let Some(rule) = rules.get(name) {
        return Ok(Some(rule.clone()));
    }
    let Some(rule) = build_named_zone_rules(name)? else {
        return Ok(None);
    };
    rules.insert(rule.canonical_name.clone(), rule.clone());
    Ok(Some(rule))
}

/// Encodes the deterministic IANA transition image consumed by native temporal backends.
pub fn resident_named_zone_table_bytes(names: &BTreeSet<String>) -> Result<Vec<u8>> {
    let mut rules = Vec::new();
    for name in names {
        if let Some(rule) = cached_named_zone_rules(name)? {
            rules.push((name, rule));
        }
    }
    let mut bytes = Vec::new();
    bytes.extend_from_slice(
        &u32::try_from(rules.len())
            .map_err(|_| Error::internal("resident IANA zone count exceeds u32"))?
            .to_le_bytes(),
    );
    for (name, rule) in rules {
        bytes.extend_from_slice(
            &u16::try_from(name.len())
                .map_err(|_| Error::internal("resident IANA zone name exceeds u16"))?
                .to_le_bytes(),
        );
        bytes.extend_from_slice(name.as_bytes());
        bytes.extend_from_slice(
            &u32::try_from(rule.intervals.len())
                .map_err(|_| Error::internal("resident IANA transition count exceeds u32"))?
                .to_le_bytes(),
        );
        for interval in rule.intervals {
            bytes.extend_from_slice(&interval.start_seconds.to_le_bytes());
            bytes.extend_from_slice(&interval.end_seconds.to_le_bytes());
            bytes.extend_from_slice(&interval.offset_seconds.to_le_bytes());
        }
    }
    u32::try_from(bytes.len())
        .map_err(|_| Error::internal("resident IANA zone table exceeds u32"))?;
    Ok(bytes)
}

