#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum ResidentNodeBinding {
    Start,
    /// A node reached before the final hop of a fixed-length resident path.  The index is zero
    /// based, so `Intermediate(0)` is the endpoint of the first expansion in a path with two or
    /// more expansions.
    Intermediate(u16),
    End,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ResidentDirection {
    Outgoing,
    Incoming,
    /// Matches either orientation while preserving Cypher's self-loop de-duplication rule.
    Undirected,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ResidentExpansion {
    pub direction: ResidentDirection,
    pub relationship_types: Vec<RelationshipTypeId>,
    pub end_labels: Vec<LabelId>,
    /// Requires the expansion endpoint to be the same resident node as its start, used for a
    /// repeated Cypher node variable such as `(n)-[r]->(n)`.
    pub end_equals_start: bool,
    /// Preserves each input start row exactly once with null relationship/end bindings when no
    /// visible expansion candidate satisfies the complete pattern.
    pub optional: bool,
    /// Pattern-local end-node predicates run before optional null extension. Later WHERE
    /// predicates remain in the pipeline predicate list and therefore retain their own null
    /// filtering semantics.
    pub end_predicates: Vec<ResidentI64Predicate>,
}

/// An OPTIONAL relationship pattern correlated to two already-bound resident path nodes.  It
/// expands from `source`, keeps only candidates whose endpoint is `target`, and null-extends
/// unmatched input rows on the selected device.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ResidentCorrelatedOptionalExpansion {
    pub source: ResidentNodeBinding,
    pub target: ResidentNodeBinding,
    pub expansion: ResidentExpansion,
}

pub const RESIDENT_NULL_ROW: u32 = u32::MAX;

/// Physical execution target.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum BackendKind {
    Cpu,
    Metal,
    Cuda,
}

/// One immutable query value consumed by a native row-local comparison matrix. Entity variants
/// carry only their Cypher type here: canonical dense identities remain in the aligned resident
/// path columns and are materialized only at the final result boundary.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum ResidentValueMatrixValue {
    Null,
    Boolean(bool),
    Integer(i64),
    Float(u64),
    String(String),
    List(Vec<Self>),
    Map,
    Node,
    Relationship,
    Path,
}

/// Expands every incoming resident graph row by the Cartesian product of `values`, evaluates the
/// requested comparison for every pair, and retains only rows where the three-valued predicate is
/// true. The pair indices are device-produced output columns, not host-selected expected values.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ResidentValueMatrixProgram {
    pub values: Vec<ResidentValueMatrixValue>,
    pub comparison: CompareOp,
    pub exclude_same_index: bool,
}

impl ResidentValueMatrixProgram {
    pub fn validate(&self) -> Result<()> {
        if self.values.is_empty() || self.values.len() > u16::MAX as usize {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "resident value matrix requires 1..=65535 root values",
            ));
        }
        if matches!(self.comparison, CompareOp::Eq | CompareOp::NotEq) {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "resident value matrix currently admits ordered comparisons only",
            ));
        }
        let mut pending = self.values.iter().collect::<Vec<_>>();
        let mut cells = 0_usize;
        while let Some(value) = pending.pop() {
            cells = cells.checked_add(1).ok_or_else(|| {
                Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "resident value matrix cell count overflow",
                )
            })?;
            if cells > RESIDENT_SCALAR_STRUCTURAL_MAX_PAIRS {
                return Err(Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "resident value matrix exceeds the bounded scalar cell arena",
                ));
            }
            if let ResidentValueMatrixValue::List(values) = value {
                pending.extend(values);
            }
        }
        Ok(())
    }

    pub fn maximum_rows(&self, input_rows: usize) -> Result<usize> {
        self.validate()?;
        input_rows
            .checked_mul(self.values.len())
            .and_then(|rows| rows.checked_mul(self.values.len()))
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "resident value matrix cardinality overflow",
                )
            })
    }
}

