/// One prefix-free, lexicographically order-preserving materialized query column. Offsets contain
/// one range per input row; `digits` reserve zero for structural terminators and contain no host-
/// ranked dictionary ordinals. Null identity remains separate so direction and null placement are
/// applied independently by the resident sorter.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ResidentOrderColumn {
    pub offsets: Vec<u32>,
    pub digits: Vec<u8>,
    pub validity: Vec<u8>,
}

/// A sort key either addresses an existing canonical node-property column or carries a bounded
/// projected expression column. Node-property values are never copied through the request.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum ResidentSortSource {
    NodeProperty {
        rows: Vec<u32>,
        property: PropertyId,
    },
    Materialized(ResidentOrderColumn),
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ResidentSortKey {
    pub source: ResidentSortSource,
    pub descending: bool,
    pub nulls_first: bool,
}

/// Stable query-row sort over one or more resident or bounded materialized keys.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ResidentSortRequest {
    pub project: ProjectId,
    pub row_count: usize,
    pub keys: Vec<ResidentSortKey>,
    pub limit: Option<usize>,
}

impl ResidentOrderColumn {
    pub fn validate(&self, row_count: usize) -> Result<usize> {
        if self.offsets.len() != row_count.saturating_add(1)
            || self.validity.len() != row_count
            || self.offsets.first().copied() != Some(0)
            || self.offsets.last().copied().map(|offset| offset as usize) != Some(self.digits.len())
            || self.offsets.windows(2).any(|pair| pair[0] > pair[1])
            || self.validity.iter().any(|valid| *valid > 1)
        {
            return Err(Error::new(
                ErrorCode::QueryType,
                "materialized resident sort column has an invalid shape",
            ));
        }
        self.offsets.windows(2).try_fold(0_usize, |maximum, pair| {
            let width = (pair[1] - pair[0]) as usize;
            Ok(maximum.max(width))
        })
    }
}

impl ResidentSortRequest {
    pub fn validate(&self) -> Result<()> {
        if self.keys.is_empty() || self.row_count > u32::MAX as usize {
            return Err(Error::new(
                ErrorCode::QueryType,
                "resident sort requires keys and a u32-addressable row stream",
            ));
        }
        for key in &self.keys {
            match &key.source {
                ResidentSortSource::NodeProperty { rows, .. } => {
                    if rows.len() != self.row_count {
                        return Err(Error::new(
                            ErrorCode::QueryType,
                            "resident property sort key row count differs from the query stream",
                        ));
                    }
                }
                ResidentSortSource::Materialized(column) => {
                    column.validate(self.row_count)?;
                }
            }
        }
        Ok(())
    }

    pub fn single_node_property(&self) -> Result<(&[u32], PropertyId, &ResidentSortKey)> {
        self.validate()?;
        let [key] = self.keys.as_slice() else {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "execution backend does not yet support multi-key resident sorting",
            ));
        };
        let ResidentSortSource::NodeProperty { rows, property } = &key.source else {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "execution backend does not yet support materialized resident sorting",
            ));
        };
        Ok((rows, *property, key))
    }
}

