    /// Exact static-label conditional node-MERGE tranche used by Merge2 [1], Merge3 [1]/[2],
    /// and Merge4 [1]. The first three are one-command programs; Merge4 additionally seals one
    /// immutable `MATCH ()` expansion before the final node MERGE.
    fn exact_node_merge_label_set_profile(&self) -> bool {
        if !self.program.input_keys.is_empty()
            || !self.program.property_names.is_empty()
            || !self.program.property_tokens.is_empty()
            || !self.program.relationship_type_names.is_empty()
            || !self.program.relationship_type_tokens.is_empty()
            || !self.program.outputs.is_empty()
            || self.program.continuation.is_some()
            || !self.merge_property_sets.is_empty()
            || self.schedule.value_slot_count != 0
            || !self.schedule.property_bindings.is_empty()
        {
            return false;
        }

        let one_command = matches!(
            (
                self.program.commands.as_slice(),
                self.commands.as_slice(),
                self.command_candidate_limits.as_slice(),
                self.schedule.stages.as_slice(),
            ),
            (
                [ResidentRowCreateCommand::CreateNode(node)],
                [ResidentRowBoundRelationshipCommand::MergeNode],
                [limit],
                [ResidentRowBoundRelationshipStage::Command { command: 0 }],
            ) if self.program.entity_slot_count == 1
                && node.output_entity == 0
                && node.properties.is_empty()
                && *limit >= 1
                && *limit <= self.capacities.resident_node_slots.max(1)
        );
        if one_command {
            let [action] = self.merge_label_sets.as_slice() else {
                return false;
            };
            if action.trigger_command != 0 || action.target_entity != 0 {
                return false;
            }
            let [ResidentRowCreateCommand::CreateNode(node)] = self.program.commands.as_slice()
            else {
                return false;
            };
            return matches!(
                (
                    node.labels.as_slice(),
                    self.program.label_names.as_slice(),
                    action.branch,
                    action.labels.as_slice(),
                    self.outputs.as_slice(),
                ),
                (
                    [0],
                    [_, _],
                    ResidentRowBoundMergeBranch::Create,
                    [1],
                    [ResidentRowBoundRelationshipOutput::Labels { entity: 0, .. }],
                )
            ) || matches!(
                (
                    node.labels.as_slice(),
                    self.program.label_names.as_slice(),
                    action.branch,
                    action.labels.as_slice(),
                    self.outputs.as_slice(),
                ),
                ([], [_], ResidentRowBoundMergeBranch::Match, [0], [],)
            ) || matches!(
                (
                    node.labels.as_slice(),
                    self.program.label_names.as_slice(),
                    action.branch,
                    action.labels.as_slice(),
                    self.outputs.as_slice(),
                ),
                (
                    [0],
                    [_, _],
                    ResidentRowBoundMergeBranch::Match,
                    [1],
                    [ResidentRowBoundRelationshipOutput::Labels { entity: 0, .. }],
                )
            );
        }

        matches!(
            (
                self.program.entity_slot_count,
                self.program.label_names.as_slice(),
                self.program.commands.as_slice(),
                self.commands.as_slice(),
                self.command_candidate_limits.as_slice(),
                self.schedule.stages.as_slice(),
                self.merge_label_sets.as_slice(),
                self.outputs.as_slice(),
            ),
            (
                2,
                [_, _, _],
                [
                    ResidentRowCreateCommand::MatchNode(matched),
                    ResidentRowCreateCommand::CreateNode(merged),
                ],
                [
                    ResidentRowBoundRelationshipCommand::MatchNode { properties },
                    ResidentRowBoundRelationshipCommand::MergeNode,
                ],
                [match_limit, merge_limit],
                [
                    ResidentRowBoundRelationshipStage::Command { command: 0 },
                    ResidentRowBoundRelationshipStage::Command { command: 1 },
                ],
                [create_action, match_action],
                [],
            ) if matched.output_entity == 0
                && matched.labels.is_empty()
                && properties.is_empty()
                && merged.output_entity == 1
                && merged.labels.as_slice() == [0]
                && merged.properties.is_empty()
                && *match_limit <= self.capacities.resident_node_slots
                && *merge_limit >= 1
                && *merge_limit <= self.capacities.resident_node_slots.saturating_add(1).max(1)
                && create_action.branch == ResidentRowBoundMergeBranch::Create
                && create_action.trigger_command == 1
                && create_action.target_entity == 1
                && create_action.labels.as_slice() == [1]
                && match_action.branch == ResidentRowBoundMergeBranch::Match
                && match_action.trigger_command == 1
                && match_action.target_entity == 1
                && match_action.labels.as_slice() == [2]
        )
    }

    /// Exact conditional-SET node-MERGE tranche used by Merge2 [2]-[4] and Merge3 [3].
    fn exact_node_merge_property_set_profile(&self) -> bool {
        if self.program.entity_slot_count != 1
            || !self.program.input_keys.is_empty()
            || self.program.property_names.len() != 1
            || self.program.property_tokens.len() != 1
            || !self.program.relationship_type_names.is_empty()
            || !self.program.relationship_type_tokens.is_empty()
            || !self.program.outputs.is_empty()
            || self.program.continuation.is_some()
            || self.schedule.value_slot_count != 0
            || !self.schedule.property_bindings.is_empty()
            || !matches!(
                self.schedule.stages.as_slice(),
                [ResidentRowBoundRelationshipStage::Command { command: 0 }]
            )
            || !matches!(
                (
                    self.program.commands.as_slice(),
                    self.commands.as_slice(),
                    self.command_candidate_limits.as_slice(),
                ),
                (
                    [ResidentRowCreateCommand::CreateNode(node)],
                    [ResidentRowBoundRelationshipCommand::MergeNode],
                    [limit],
                ) if node.output_entity == 0
                    && node.properties.is_empty()
                    && *limit >= 1
                    && *limit <= self.capacities.resident_node_slots.max(1)
            )
        {
            return false;
        }

        let [action] = self.merge_property_sets.as_slice() else {
            return false;
        };
        if action.mode != ResidentRowBoundMergePropertyMode::Set
            || action.trigger_command != 0
            || action.target_entity != 0
            || action.property_name != 0
        {
            return false;
        }
        let [ResidentRowCreateCommand::CreateNode(node)] = self.program.commands.as_slice() else {
            return false;
        };
        match (action.branch, &action.source) {
            (
                ResidentRowBoundMergeBranch::Create,
                ResidentRowBoundMergePropertySource::Constant(ScalarValue::Integer(1)),
            ) => {
                node.labels.is_empty()
                    && self.program.label_names.is_empty()
                    && self.program.label_tokens.is_empty()
                    && self.program.property_names.as_slice() == ["created"]
                    && self.outputs.is_empty()
            }
            (
                ResidentRowBoundMergeBranch::Create | ResidentRowBoundMergeBranch::Match,
                ResidentRowBoundMergePropertySource::Constant(ScalarValue::Integer(42)),
            ) => {
                node.labels.as_slice() == [0]
                    && self.program.label_names.as_slice() == ["TheLabel"]
                    && self.program.label_tokens.len() == 1
                    && self.program.property_names.as_slice() == ["num"]
                    && matches!(
                        self.outputs.as_slice(),
                        [ResidentRowBoundRelationshipOutput::Property {
                            entity: 0,
                            property_name: 0,
                            ..
                        }]
                    )
            }
            _ => false,
        }
    }

    /// Request-side mirror of Merge2 [5], Merge3 [4], and Merge4 [2]. One immutable Person row
