/// Constructs exactly the resolved backend or fails; it never changes execution class.
pub fn create_execution_backend(
    resolved: ResolvedComputeDevice,
    memory_limit_bytes: usize,
    reserved_bytes: usize,
) -> Result<Box<dyn ExecutionBackend>> {
    create_execution_backend_with_governor(
        resolved,
        DeviceMemoryGovernor::new(memory_limit_bytes, reserved_bytes),
    )
}

/// Constructs a backend that participates in the caller's process-wide graph/encoder ledger.
pub fn create_execution_backend_with_governor(
    resolved: ResolvedComputeDevice,
    governor: DeviceMemoryGovernor,
) -> Result<Box<dyn ExecutionBackend>> {
    match resolved.backend {
        BackendKind::Cpu => Ok(Box::new(CpuBackend::with_governor(governor))),
        BackendKind::Metal => {
            #[cfg(all(feature = "accelerator", any(target_os = "macos", target_os = "ios")))]
            {
                Ok(Box::new(MetalBackend::with_governor(
                    resolved.ordinal as usize,
                    governor,
                )?))
            }
            #[cfg(not(all(feature = "accelerator", any(target_os = "macos", target_os = "ios"))))]
            {
                Err(Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "resolved Metal execution requires a Metal-enabled binary",
                ))
            }
        }
        BackendKind::Cuda => {
            #[cfg(feature = "cuda")]
            {
                Ok(Box::new(CudaBackend::with_governor(
                    resolved.ordinal as usize,
                    governor,
                )?))
            }
            #[cfg(not(feature = "cuda"))]
            {
                Err(Error::new(
                    ErrorCode::GpuAdmissionFailure,
                    "resolved CUDA execution requires a CUDA-enabled binary",
                ))
            }
        }
    }
}

pub fn ensure_not_cancelled(cancellation: &CancellationToken) -> Result<()> {
    if cancellation.is_cancelled() {
        return Err(Error::new(ErrorCode::Cancelled, "GPU operation cancelled"));
    }
    Ok(())
}

/// Checks the complete in-flight execution guard for a resident graph procedure.
///
/// Cancellation deliberately wins when both conditions are true. This matches the query
/// executor's public error precedence and keeps the result deterministic at a dispatch boundary.
pub fn ensure_graph_execution(
    cancellation: &CancellationToken,
    deadline: Option<Instant>,
) -> Result<()> {
    ensure_not_cancelled(cancellation)?;
    if deadline.is_some_and(|deadline| Instant::now() >= deadline) {
        return Err(Error::new(
            ErrorCode::DeadlineExceeded,
            "GPU graph operation deadline exceeded",
        ));
    }
    Ok(())
}

pub fn operator_scratch_bytes(
    input_rows: usize,
    bytes_per_input: usize,
    output_rows: usize,
    bytes_per_output: usize,
) -> Result<usize> {
    input_rows
        .checked_mul(bytes_per_input)
        .and_then(|input_bytes| {
            output_rows
                .checked_mul(bytes_per_output)
                .and_then(|output_bytes| input_bytes.checked_add(output_bytes))
        })
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "device operator scratch shape overflow",
            )
        })
}

pub const METAL_I64_SORT_FIXED_SCRATCH_BYTES: usize = 4_096;
pub const METAL_SORT_TILE_ROWS: usize = 1_024;
pub const METAL_TOP_K_MAX_ROWS: usize = 256;

fn metal_shared_buffer_bytes(logical: usize) -> Result<usize> {
    if logical == 0 {
        return Ok(0);
    }
    logical
        .checked_add(METAL_I64_SORT_FIXED_SCRATCH_BYTES - 1)
        .map(|bytes| bytes / METAL_I64_SORT_FIXED_SCRATCH_BYTES)
        .and_then(|pages| pages.checked_mul(METAL_I64_SORT_FIXED_SCRATCH_BYTES))
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal shared sort-buffer shape overflow",
            )
        })
}

fn metal_private_buffer_bytes(logical: usize) -> Result<usize> {
    if logical == 0 {
        return Ok(0);
    }
    logical
        .checked_next_power_of_two()
        .map(|bytes| bytes.max(METAL_I64_SORT_FIXED_SCRATCH_BYTES))
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal private sort-buffer shape overflow",
            )
        })
}

pub fn metal_i64_sort_scratch_bytes(input_rows: usize, output_rows: usize) -> Result<usize> {
    if input_rows == 0 || output_rows == 0 {
        return Ok(0);
    }
    let shared_rows =
        metal_shared_buffer_bytes(input_rows.checked_mul(size_of::<u32>()).ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal sort row shape overflow",
            )
        })?)?;
    let selected_values =
        metal_private_buffer_bytes(input_rows.checked_mul(size_of::<i64>()).ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal sort value shape overflow",
            )
        })?)?;
    let selected_validity = metal_private_buffer_bytes(input_rows)?;
    let positions =
        metal_shared_buffer_bytes(input_rows.checked_mul(size_of::<u32>()).ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal sort position shape overflow",
            )
        })?)?;
    let operator = if output_rows <= METAL_TOP_K_MAX_ROWS {
        let blocks = input_rows.div_ceil(METAL_SORT_TILE_ROWS);
        let full_blocks = input_rows / METAL_SORT_TILE_ROWS;
        let remainder = input_rows % METAL_SORT_TILE_ROWS;
        let first_output = full_blocks
            .checked_mul(output_rows)
            .and_then(|rows| rows.checked_add(remainder.min(output_rows)))
            .and_then(|rows| rows.checked_mul(size_of::<u32>()))
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal top-k output shape overflow",
                )
            })?;
        if blocks == 0 {
            0
        } else {
            metal_private_buffer_bytes(first_output)?
        }
    } else {
        let output = metal_private_buffer_bytes(
            input_rows.checked_mul(size_of::<u32>()).ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal radix output shape overflow",
                )
            })?,
        )?;
        let table = metal_private_buffer_bytes(
            input_rows
                .div_ceil(METAL_SORT_TILE_ROWS)
                .checked_mul(256)
                .and_then(|values| values.checked_mul(size_of::<u32>()))
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal radix table shape overflow",
                    )
                })?,
        )?;
        output.checked_add(table.saturating_mul(2)).ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal radix scratch shape overflow",
            )
        })?
    };
    shared_rows
        .checked_add(selected_values)
        .and_then(|bytes| bytes.checked_add(selected_validity))
        .and_then(|bytes| bytes.checked_add(positions))
        .and_then(|bytes| bytes.checked_add(operator))
        .and_then(|bytes| bytes.checked_add(METAL_I64_SORT_FIXED_SCRATCH_BYTES))
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal integer sort scratch shape overflow",
            )
        })
}

#[cfg(any(target_os = "macos", target_os = "ios"))]
pub fn metal_sort_scratch_bytes(request: &ResidentSortRequest) -> Result<usize> {
    request.validate()?;
    if request.single_node_property().is_ok() {
        return metal_i64_sort_scratch_bytes(
            request.row_count,
            request
                .limit
                .unwrap_or(request.row_count)
                .min(request.row_count),
        );
    }
    if request
        .keys
        .iter()
        .any(|key| !matches!(key.source, ResidentSortSource::Materialized(_)))
    {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "Metal sort request mixes unsupported resident key sources",
        ));
    }
    if request.row_count == 0 {
        return Ok(0);
    }
    let materialized_peak = request.keys.iter().try_fold(0_usize, |peak, key| {
        let ResidentSortSource::Materialized(column) = &key.source else {
            return Err(Error::internal(
                "materialized Metal sort validation changed during accounting",
            ));
        };
        let offsets = metal_shared_buffer_bytes(
            column
                .offsets
                .len()
                .checked_mul(size_of::<u32>())
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "Metal sort offset upload shape overflow",
                    )
                })?,
        )?;
        let digits = metal_shared_buffer_bytes(column.digits.len().max(1))?;
        let validity = metal_shared_buffer_bytes(column.validity.len())?;
        offsets
            .checked_add(digits)
            .and_then(|bytes| bytes.checked_add(validity))
            .map(|bytes| peak.max(bytes))
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal materialized sort upload shape overflow",
                )
            })
    })?;
    let positions =
        metal_private_buffer_bytes(request.row_count.checked_mul(size_of::<u32>()).ok_or_else(
            || {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal encoded sort position shape overflow",
                )
            },
        )?)?;
    let table = metal_private_buffer_bytes(
        request
            .row_count
            .div_ceil(METAL_SORT_TILE_ROWS)
            .checked_mul(256)
            .and_then(|values| values.checked_mul(size_of::<u32>()))
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "Metal encoded radix table shape overflow",
                )
            })?,
    )?;
    materialized_peak
        .checked_add(positions.saturating_mul(2))
        .and_then(|bytes| bytes.checked_add(table.saturating_mul(2)))
        .and_then(|bytes| bytes.checked_add(METAL_I64_SORT_FIXED_SCRATCH_BYTES))
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "Metal encoded sort scratch shape overflow",
            )
        })
}

#[cfg(test)]
mod pattern_predicate_receipt_tests {
    use super::*;

    const BOOKMARK: Bookmark = Bookmark { term: 2, index: 3 };
    const REVISION: u64 = 5;
    const LAYOUT_VERSION: u64 = 7;

    fn obligation(
        id: u64,
        kind: ResidentObligationKind,
        scope: ResidentObligationScope,
    ) -> ResidentExecutionObligation {
        ResidentExecutionObligation { id, kind, scope }
    }

    fn request() -> ResidentPatternPredicateRequest {
        ResidentPatternPredicateRequest {
            project: ProjectId(uuid::Uuid::nil()),
            expected_bookmark: BOOKMARK,
            expected_graph_revision: REVISION,
            expected_layout_version: LAYOUT_VERSION,
            layers: LayerMask::OBSERVED,
            input: ResidentPatternPredicateInput::Rows(vec![4, 4, 7]),
            program: ResidentPatternPredicateProgram {
                execution: ResidentExecutionId { high: 8, low: 13 },
                leaves: vec![ResidentPatternPredicateLeaf {
                    direction: ResidentDirection::Outgoing,
                    relationship_types: ResidentPatternRelationshipTypes::Any,
                    length: ResidentPatternPredicateLength::One,
                    property_equality: None,
                    minimum_witnesses: 1,
                    maximum_witnesses: u32::MAX,
                    obligation: obligation(
                        21,
                        ResidentObligationKind::PatternTraversal,
                        ResidentObligationScope::PatternLeaf(0),
                    ),
                }],
                instructions: vec![ResidentPatternBooleanInstruction::Leaf(0)],
                final_obligation: obligation(
                    22,
                    ResidentObligationKind::PatternFilter,
                    ResidentObligationScope::PatternFinal,
                ),
            },
            max_output_rows: 3,
        }
    }

    fn valid_result(request: &ResidentPatternPredicateRequest) -> ResidentPatternPredicateResult {
        let completion = ResidentDeviceCompletion::CpuReference;
        ResidentPatternPredicateResult::completed(
            request.program.execution,
            request.expected_bookmark,
            request.expected_graph_revision,
            request.expected_layout_version,
            vec![4, 4, 7],
            vec![
                ResidentExecutionReceipt {
                    execution: request.program.execution,
                    obligation: request.program.leaves[0].obligation,
                    input_cardinality: 3,
                    output_cardinality: 3,
                    completion,
                },
                ResidentExecutionReceipt {
                    execution: request.program.execution,
                    obligation: request.program.final_obligation,
                    input_cardinality: 3,
                    output_cardinality: 3,
                    completion,
                },
            ],
        )
    }

    #[test]
    fn validates_exact_pattern_receipts_and_stable_semijoin_rows() -> Result<()> {
        let request = request();
        request.validate()?;
        let result = valid_result(&request).validate(&request, BackendKind::Cpu)?;
        assert_eq!(result.rows(), [4, 4, 7]);
        assert_eq!(result.bookmark(), BOOKMARK);
        assert_eq!(result.graph_revision(), REVISION);
        assert_eq!(result.layout_version(), LAYOUT_VERSION);
        assert_eq!(result.receipts().len(), 2);
        Ok(())
    }

    #[test]
    fn rejects_wrong_execution_backend_and_corrupt_pattern_receipts() {
        let request = request();

        let mut wrong_execution = valid_result(&request);
        wrong_execution.execution.low += 1;
        assert!(
            wrong_execution
                .validate(&request, BackendKind::Cpu)
                .is_err()
        );
        assert!(
            valid_result(&request)
                .validate(&request, BackendKind::Metal)
                .is_err()
        );

        let mut wrong_bookmark = valid_result(&request);
        wrong_bookmark.bookmark.index += 1;
        assert!(wrong_bookmark.validate(&request, BackendKind::Cpu).is_err());

        let mut wrong_revision = valid_result(&request);
        wrong_revision.graph_revision += 1;
        assert!(wrong_revision.validate(&request, BackendKind::Cpu).is_err());

        let mut wrong_layout = valid_result(&request);
        wrong_layout.layout_version += 1;
        assert!(wrong_layout.validate(&request, BackendKind::Cpu).is_err());

        let mut missing = valid_result(&request);
        missing.receipts.pop();
        assert!(missing.validate(&request, BackendKind::Cpu).is_err());

        let mut duplicate = valid_result(&request);
        duplicate.receipts[1] = duplicate.receipts[0];
        assert!(duplicate.validate(&request, BackendKind::Cpu).is_err());

        let mut reordered = valid_result(&request);
        reordered.receipts.reverse();
        assert!(reordered.validate(&request, BackendKind::Cpu).is_err());

        let mut impossible = valid_result(&request);
        impossible.receipts[0].output_cardinality = 4;
        assert!(impossible.validate(&request, BackendKind::Cpu).is_err());
    }

    #[test]
    fn rejects_row_multiplication_and_unstable_compaction() {
        let request = request();
        let mut multiplied = valid_result(&request);
        multiplied.output_rows = vec![4, 4, 4, 7];
        multiplied.receipts[1].output_cardinality = 4;
        assert!(multiplied.validate(&request, BackendKind::Cpu).is_err());

        let mut reordered = valid_result(&request);
        reordered.output_rows = vec![7, 4, 4];
        assert!(reordered.validate(&request, BackendKind::Cpu).is_err());

        let mut thinned_duplicate = valid_result(&request);
        thinned_duplicate.output_rows = vec![4, 7];
        thinned_duplicate.receipts[0].output_cardinality = 2;
        thinned_duplicate.receipts[1].output_cardinality = 2;
        assert!(
            thinned_duplicate
                .validate(&request, BackendKind::Cpu)
                .is_err()
        );
    }

    fn scan_request() -> ResidentPatternPredicateRequest {
        let mut request = request();
        request.input = ResidentPatternPredicateInput::VisibleNodeScan {
            node_slots: 5,
            obligation: obligation(
                20,
                ResidentObligationKind::PatternScan,
                ResidentObligationScope::PatternScan,
            ),
        };
        request.max_output_rows = 5;
        request
    }

    fn valid_scan_result(
        request: &ResidentPatternPredicateRequest,
    ) -> ResidentPatternPredicateResult {
        ResidentPatternPredicateResult::completed(
            request.program.execution,
            request.expected_bookmark,
            request.expected_graph_revision,
            request.expected_layout_version,
            vec![0, 3],
            vec![
                ResidentExecutionReceipt {
                    execution: request.program.execution,
                    obligation: obligation(
                        20,
                        ResidentObligationKind::PatternScan,
                        ResidentObligationScope::PatternScan,
                    ),
                    input_cardinality: 5,
                    output_cardinality: 3,
                    completion: ResidentDeviceCompletion::CpuReference,
                },
                ResidentExecutionReceipt {
                    execution: request.program.execution,
                    obligation: request.program.leaves[0].obligation,
                    input_cardinality: 3,
                    output_cardinality: 2,
                    completion: ResidentDeviceCompletion::CpuReference,
                },
                ResidentExecutionReceipt {
                    execution: request.program.execution,
                    obligation: request.program.final_obligation,
                    input_cardinality: 3,
                    output_cardinality: 2,
                    completion: ResidentDeviceCompletion::CpuReference,
                },
            ],
        )
    }

    #[test]
    fn validates_pattern_scan_receipt_and_rejects_scan_corruption() -> Result<()> {
        let request = scan_request();
        let result = valid_scan_result(&request).validate(&request, BackendKind::Cpu)?;
        assert_eq!(result.rows(), [0, 3]);
        assert_eq!(
            result.receipts()[0].obligation.scope,
            ResidentObligationScope::PatternScan
        );

        let mut missing = valid_scan_result(&request);
        missing.receipts.remove(0);
        assert!(missing.validate(&request, BackendKind::Cpu).is_err());

        let mut reordered = valid_scan_result(&request);
        reordered.receipts.swap(0, 1);
        assert!(reordered.validate(&request, BackendKind::Cpu).is_err());

        let mut impossible_slots = valid_scan_result(&request);
        impossible_slots.receipts[0].input_cardinality = 4;
        assert!(
            impossible_slots
                .validate(&request, BackendKind::Cpu)
                .is_err()
        );

        let mut inconsistent_leaf_input = valid_scan_result(&request);
        inconsistent_leaf_input.receipts[1].input_cardinality = 5;
        assert!(
            inconsistent_leaf_input
                .validate(&request, BackendKind::Cpu)
                .is_err()
        );

        let mut duplicate_output = valid_scan_result(&request);
        duplicate_output.output_rows = vec![0, 0];
        assert!(
            duplicate_output
                .validate(&request, BackendKind::Cpu)
                .is_err()
        );
        Ok(())
    }

    fn boolean_request(
        leaf_count: usize,
        instructions: Vec<ResidentPatternBooleanInstruction>,
    ) -> ResidentPatternPredicateRequest {
        let mut request = request();
        request.input = ResidentPatternPredicateInput::Rows((0..10).collect());
        request.max_output_rows = 10;
        request.program.leaves = (0..leaf_count)
            .map(|index| ResidentPatternPredicateLeaf {
                direction: ResidentDirection::Outgoing,
                relationship_types: ResidentPatternRelationshipTypes::Any,
                length: ResidentPatternPredicateLength::One,
                property_equality: None,
                minimum_witnesses: 1,
                maximum_witnesses: u32::MAX,
                obligation: obligation(
                    100 + index as u64,
                    ResidentObligationKind::PatternTraversal,
                    ResidentObligationScope::PatternLeaf(index as u16),
                ),
            })
            .collect();
        request.program.instructions = instructions;
        request
    }

    fn boolean_result(
        request: &ResidentPatternPredicateRequest,
        leaf_cardinalities: &[u64],
        final_cardinality: usize,
    ) -> ResidentPatternPredicateResult {
        let mut receipts = request
            .program
            .leaves
            .iter()
            .zip(leaf_cardinalities)
            .map(|(leaf, cardinality)| ResidentExecutionReceipt {
                execution: request.program.execution,
                obligation: leaf.obligation,
                input_cardinality: 10,
                output_cardinality: *cardinality,
                completion: ResidentDeviceCompletion::CpuReference,
            })
            .collect::<Vec<_>>();
        receipts.push(ResidentExecutionReceipt {
            execution: request.program.execution,
            obligation: request.program.final_obligation,
            input_cardinality: 10,
            output_cardinality: final_cardinality as u64,
            completion: ResidentDeviceCompletion::CpuReference,
        });
        ResidentPatternPredicateResult::completed(
            request.program.execution,
            request.expected_bookmark,
            request.expected_graph_revision,
            request.expected_layout_version,
            (0..final_cardinality as u32).collect(),
            receipts,
        )
    }

    #[test]
    fn one_hop_constraint_abi_rejects_invalid_bounds_and_variable_length_attachment() {
        let mut candidate = request();
        candidate.program.leaves[0].minimum_witnesses = 0;
        assert!(candidate.validate().is_err());

        let mut candidate = request();
        candidate.program.leaves[0].minimum_witnesses = 3;
        candidate.program.leaves[0].maximum_witnesses = 2;
        assert!(candidate.validate().is_err());

        let mut candidate = request();
        candidate.program.leaves[0].length = ResidentPatternPredicateLength::ExactTwo;
        candidate.program.leaves[0].property_equality =
            Some(ResidentPatternPredicatePropertyEquality {
                start: PropertyId(1),
                end: PropertyId(1),
            });
        assert!(candidate.validate().is_err());

        let mut candidate = request();
        candidate.program.leaves[0].minimum_witnesses = 2;
        candidate.program.leaves[0].maximum_witnesses = 2;
        assert!(candidate.validate().is_ok());
    }

    #[test]
    fn validates_leaf_not_and_feasible_and_or_cardinality_bounds() -> Result<()> {
        let leaf = boolean_request(1, vec![ResidentPatternBooleanInstruction::Leaf(0)]);
        boolean_result(&leaf, &[7], 7).validate(&leaf, BackendKind::Cpu)?;
        assert!(
            boolean_result(&leaf, &[7], 6)
                .validate(&leaf, BackendKind::Cpu)
                .is_err()
        );

        let not = boolean_request(
            1,
            vec![
                ResidentPatternBooleanInstruction::Leaf(0),
                ResidentPatternBooleanInstruction::Not,
            ],
        );
        boolean_result(&not, &[7], 3).validate(&not, BackendKind::Cpu)?;
        assert!(
            boolean_result(&not, &[7], 4)
                .validate(&not, BackendKind::Cpu)
                .is_err()
        );

        let and = boolean_request(
            2,
            vec![
                ResidentPatternBooleanInstruction::Leaf(0),
                ResidentPatternBooleanInstruction::Leaf(1),
                ResidentPatternBooleanInstruction::And,
            ],
        );
        boolean_result(&and, &[7, 6], 3).validate(&and, BackendKind::Cpu)?;
        boolean_result(&and, &[7, 6], 6).validate(&and, BackendKind::Cpu)?;
        assert!(
            boolean_result(&and, &[7, 6], 2)
                .validate(&and, BackendKind::Cpu)
                .is_err()
        );
        assert!(
            boolean_result(&and, &[7, 6], 7)
                .validate(&and, BackendKind::Cpu)
                .is_err()
        );

        let or = boolean_request(
            2,
            vec![
                ResidentPatternBooleanInstruction::Leaf(0),
                ResidentPatternBooleanInstruction::Leaf(1),
                ResidentPatternBooleanInstruction::Or,
            ],
        );
        boolean_result(&or, &[7, 6], 7).validate(&or, BackendKind::Cpu)?;
        boolean_result(&or, &[7, 6], 10).validate(&or, BackendKind::Cpu)?;
        assert!(
            boolean_result(&or, &[7, 6], 6)
                .validate(&or, BackendKind::Cpu)
                .is_err()
        );
        Ok(())
    }
}

#[cfg(test)]
mod pattern_pair_predicate_receipt_tests {
    use super::*;

    fn obligation(
        id: u64,
        kind: ResidentObligationKind,
        scope: ResidentObligationScope,
    ) -> ResidentExecutionObligation {
        ResidentExecutionObligation { id, kind, scope }
    }

    fn request() -> ResidentPatternPairPredicateRequest {
        ResidentPatternPairPredicateRequest {
            project: ProjectId(uuid::Uuid::nil()),
            expected_bookmark: Bookmark { term: 3, index: 5 },
            expected_graph_revision: 8,
            expected_layout_version: 13,
            layers: LayerMask::OBSERVED,
            input: ResidentPatternPairVisibleNodeScans {
                node_slots: 3,
                n_obligation: obligation(
                    20,
                    ResidentObligationKind::PatternScan,
                    ResidentObligationScope::PatternScanN,
                ),
                m_obligation: obligation(
                    21,
                    ResidentObligationKind::PatternScan,
                    ResidentObligationScope::PatternScanM,
                ),
                cartesian_obligation: obligation(
                    22,
                    ResidentObligationKind::PatternCartesian,
                    ResidentObligationScope::PatternCartesian,
                ),
            },
            program: ResidentPatternPairPredicateProgram {
                execution: ResidentExecutionId { high: 34, low: 55 },
                leaf: ResidentPatternPairPredicateLeaf {
                    direction: ResidentDirection::Undirected,
                    relationship_types: ResidentPatternRelationshipTypes::Any,
                    length: ResidentPatternPairPredicateLength::OneOrMoreReachable,
                    obligation: obligation(
                        23,
                        ResidentObligationKind::PatternTraversal,
                        ResidentObligationScope::PatternLeaf(0),
                    ),
                },
                final_obligation: obligation(
                    24,
                    ResidentObligationKind::PatternFilter,
                    ResidentObligationScope::PatternFinal,
                ),
            },
            max_output_pairs: 4,
        }
    }

    fn valid_result(
        request: &ResidentPatternPairPredicateRequest,
    ) -> ResidentPatternPairPredicateResult {
        let execution = request.program.execution;
        let completion = ResidentDeviceCompletion::CpuReference;
        ResidentPatternPairPredicateResult::completed(
            execution,
            request.expected_bookmark,
            request.expected_graph_revision,
            request.expected_layout_version,
            vec![1, 6],
            vec![0, 2],
            vec![1, 0],
            vec![
                ResidentExecutionReceipt {
                    execution,
                    obligation: request.input.n_obligation,
                    input_cardinality: 3,
                    output_cardinality: 2,
                    completion,
                },
                ResidentExecutionReceipt {
                    execution,
                    obligation: request.input.m_obligation,
                    input_cardinality: 3,
                    output_cardinality: 2,
                    completion,
                },
                ResidentExecutionReceipt {
                    execution,
                    obligation: request.input.cartesian_obligation,
                    input_cardinality: 4,
                    output_cardinality: 4,
                    completion,
                },
                ResidentExecutionReceipt {
                    execution,
                    obligation: request.program.leaf.obligation,
                    input_cardinality: 4,
                    output_cardinality: 2,
                    completion,
                },
                ResidentExecutionReceipt {
                    execution,
                    obligation: request.program.final_obligation,
                    input_cardinality: 4,
                    output_cardinality: 2,
                    completion,
                },
            ],
        )
    }

    #[test]
    fn validates_exact_paired_receipts_and_row_major_alignment() -> Result<()> {
        let request = request();
        request.validate()?;
        let result = valid_result(&request).validate(&request, BackendKind::Cpu)?;
        assert_eq!(result.pair_positions(), [1, 6]);
        assert_eq!(result.n_rows(), [0, 2]);
        assert_eq!(result.m_rows(), [1, 0]);
        assert_eq!(
            result
                .receipts()
                .iter()
                .map(|receipt| receipt.obligation.scope)
                .collect::<Vec<_>>(),
            vec![
                ResidentObligationScope::PatternScanN,
                ResidentObligationScope::PatternScanM,
                ResidentObligationScope::PatternCartesian,
                ResidentObligationScope::PatternLeaf(0),
                ResidentObligationScope::PatternFinal,
            ]
        );
        Ok(())
    }

    #[test]
    fn rejects_paired_identity_receipt_and_alignment_corruption() {
        let request = request();

        let mut stale = valid_result(&request);
        stale.layout_version += 1;
        assert!(stale.validate(&request, BackendKind::Cpu).is_err());
        assert!(
            valid_result(&request)
                .validate(&request, BackendKind::Metal)
                .is_err()
        );

        let mut missing = valid_result(&request);
        missing.receipts.remove(1);
        assert!(missing.validate(&request, BackendKind::Cpu).is_err());
        let mut reordered = valid_result(&request);
        reordered.receipts.swap(0, 1);
        assert!(reordered.validate(&request, BackendKind::Cpu).is_err());
        let mut duplicate = valid_result(&request);
        duplicate.receipts[1] = duplicate.receipts[0];
        assert!(duplicate.validate(&request, BackendKind::Cpu).is_err());

        let mut bad_scan = valid_result(&request);
        bad_scan.receipts[1].output_cardinality = 1;
        assert!(bad_scan.validate(&request, BackendKind::Cpu).is_err());
        let mut bad_cartesian = valid_result(&request);
        bad_cartesian.receipts[2].output_cardinality = 3;
        assert!(bad_cartesian.validate(&request, BackendKind::Cpu).is_err());
        let mut bad_traversal = valid_result(&request);
        bad_traversal.receipts[3].output_cardinality = 5;
        assert!(bad_traversal.validate(&request, BackendKind::Cpu).is_err());
        let mut bad_final = valid_result(&request);
        bad_final.receipts[4].output_cardinality = 1;
        assert!(bad_final.validate(&request, BackendKind::Cpu).is_err());

        let mut wrong_position = valid_result(&request);
        wrong_position.pair_positions[0] = 2;
        assert!(wrong_position.validate(&request, BackendKind::Cpu).is_err());
        let mut reordered_pairs = valid_result(&request);
        reordered_pairs.pair_positions.reverse();
        reordered_pairs.n_rows.reverse();
        reordered_pairs.m_rows.reverse();
        assert!(
            reordered_pairs
                .validate(&request, BackendKind::Cpu)
                .is_err()
        );
        let mut misaligned = valid_result(&request);
        misaligned.m_rows.pop();
        assert!(misaligned.validate(&request, BackendKind::Cpu).is_err());
    }

    #[test]
    fn paired_request_crosses_the_former_domain_and_preserves_physical_locator_validation()
    -> Result<()> {
        let mut above_former_domain = request();
        above_former_domain.input.node_slots = 257;
        above_former_domain.max_output_pairs = 257 * 257;
        above_former_domain.validate()?;
        assert_eq!(above_former_domain.logical_pair_domain()?, 66_049);

        let mut chunked_reachability = request();
        chunked_reachability.input.node_slots = 1_025;
        chunked_reachability.max_output_pairs = 0;
        chunked_reachability.validate()?;
        assert_eq!(chunked_reachability.logical_pair_domain()?, 1_050_625);
        assert!(chunked_reachability.pair_chunk_rows()? < 1_050_625);
        assert!(chunked_reachability.scratch_bytes()? > 0);

        let mut chunked_direct_pair = chunked_reachability.clone();
        chunked_direct_pair.program.leaf.length = ResidentPatternPairPredicateLength::One;
        assert_eq!(
            chunked_direct_pair.pair_chunk_rows()?,
            RESIDENT_PATTERN_PAIR_CHUNK_ROWS
        );

        if let Some(too_many_physical_slots) = (u32::MAX as usize).checked_add(1) {
            let mut outside_graph_locator_width = request();
            outside_graph_locator_width.input.node_slots = too_many_physical_slots;
            assert!(outside_graph_locator_width.validate().is_err());
        }
        let mut one_over_output = request();
        one_over_output.max_output_pairs = one_over_output.pair_domain()?.checked_add(1).unwrap();
        assert!(one_over_output.validate().is_err());
        let mut duplicate = request();
        duplicate.input.m_obligation.id = duplicate.input.n_obligation.id;
        assert!(duplicate.validate().is_err());
        Ok(())
    }
}

#[cfg(test)]
