    fn receipted_request() -> ResidentNodePipelineRequest {
        let mut request = request_with_all_filter_boundaries();
        request.continuations.clear();
        request.correlated_optional = None;
        request.relationship_null_filter = None;
        request.predicates.truncate(1);
        request.property_filters.clear();
        request.value_matrix = None;
        let execution = ResidentExecutionId { high: 11, low: 29 };
        let obligation = |id, kind, scope| ResidentExecutionObligation { id, kind, scope };
        request.mutation = Some(ResidentMutationProgram {
            execution,
            selection_obligation: obligation(
                1,
                ResidentObligationKind::MutationSelect,
                ResidentObligationScope::Selection,
            ),
            filter_obligations: vec![
                obligation(
                    2,
                    ResidentObligationKind::Filter,
                    ResidentObligationScope::Filter(0),
                ),
                obligation(
                    3,
                    ResidentObligationKind::Filter,
                    ResidentObligationScope::Filter(1),
                ),
                obligation(
                    4,
                    ResidentObligationKind::Filter,
                    ResidentObligationScope::Filter(2),
                ),
            ],
            expression_obligations: Vec::new(),
            property_names: Vec::new(),
            property_tokens: Vec::new(),
            label_names: vec!["Touched".to_owned()],
            label_tokens: vec![None],
            values: Vec::new(),
            commands: vec![ResidentMutationCommand {
                rhs_obligation: obligation(
                    5,
                    ResidentObligationKind::MutationRhs,
                    ResidentObligationScope::MutationCommand(0),
                ),
                effect_obligation: obligation(
                    6,
                    ResidentObligationKind::MutationEffect,
                    ResidentObligationScope::MutationCommand(0),
                ),
                value_start: 0,
                value_count: 0,
                operation: ResidentMutationOperation::AddLabels {
                    target: ResidentNodeBinding::Start,
                    labels: vec![0],
                },
            }],
            max_intents: 1,
            continuation: None,
        });
        request
    }

    fn valid_receipts(request: &ResidentNodePipelineRequest) -> Vec<ResidentExecutionReceipt> {
        let program = request.mutation.as_ref().expect("mutation program");
        let receipt =
            |obligation, input_cardinality, output_cardinality| ResidentExecutionReceipt {
                execution: program.execution,
                obligation,
                input_cardinality,
                output_cardinality,
                completion: ResidentDeviceCompletion::CpuReference,
            };
        vec![
            receipt(program.selection_obligation, 2, 1),
            receipt(program.filter_obligations[0], 4, 3),
            receipt(program.filter_obligations[1], 3, 2),
            receipt(program.filter_obligations[2], 2, 1),
            receipt(program.commands[0].rhs_obligation, 1, 1),
            receipt(program.commands[0].effect_obligation, 1, 1),
        ]
    }

    #[test]
    fn publication_validates_candidate_and_selected_filter_cardinalities() -> crate::Result<()> {
        let request = receipted_request();
        let program = request.mutation.as_ref().expect("mutation program");
        let intents = vec![ResidentMutationIntent {
            source_row: 0,
            command: 0,
            target_kind: EntityKind::Node,
            target_id: 41,
            action: ResidentMutationIntentAction::AddLabels { labels: vec![0] },
            effectful: true,
        }];
        ResidentMutationProgramResult::completed(
            program.execution,
            intents.clone(),
            valid_receipts(&request),
        )
        .validate_for_publication(&request, BackendKind::Cpu)?;

        let mut broken = valid_receipts(&request);
        broken[2].input_cardinality = 4;
        assert!(
            ResidentMutationProgramResult::completed(program.execution, intents, broken)
                .validate_for_publication(&request, BackendKind::Cpu)
                .is_err()
        );
        Ok(())
    }

    #[test]
    fn publication_binds_effect_flags_to_exact_ordered_receipts() -> crate::Result<()> {
        let request = receipted_request();
        let program = request.mutation.as_ref().expect("mutation program");
        let effect_receipt = valid_receipts(&request)
            .iter()
            .position(|receipt| receipt.obligation == program.commands[0].effect_obligation)
            .expect("effect receipt");
        let rhs_receipt = valid_receipts(&request)
            .iter()
            .position(|receipt| receipt.obligation == program.commands[0].rhs_obligation)
            .expect("RHS receipt");
        let intent = ResidentMutationIntent {
            source_row: 0,
            command: 0,
            target_kind: EntityKind::Node,
            target_id: 41,
            action: ResidentMutationIntentAction::AddLabels { labels: vec![0] },
            effectful: true,
        };

        let mut forged_count = ResidentMutationProgramResult::completed(
            program.execution,
            vec![intent.clone()],
            valid_receipts(&request),
        );
        forged_count.receipts[effect_receipt].output_cardinality = 0;
        assert!(
            forged_count
                .validate_for_publication(&request, BackendKind::Cpu)
                .is_err()
        );

        let mut hidden_effect = ResidentMutationProgramResult::completed(
            program.execution,
            vec![ResidentMutationIntent {
                action: ResidentMutationIntentAction::AddLabels { labels: Vec::new() },
                effectful: false,
                ..intent.clone()
            }],
            valid_receipts(&request),
        );
        assert!(
            hidden_effect
                .clone()
                .validate_for_publication(&request, BackendKind::Cpu)
                .is_err()
        );
        hidden_effect.receipts[effect_receipt].output_cardinality = 0;
        let no_op = hidden_effect.validate_for_publication(&request, BackendKind::Cpu)?;
        assert!(no_op.intents().is_empty());

        let mut forged_input = ResidentMutationProgramResult::completed(
            program.execution,
            vec![intent.clone()],
            valid_receipts(&request),
        );
        forged_input.receipts[effect_receipt].input_cardinality = 0;
        assert!(
            forged_input
                .validate_for_publication(&request, BackendKind::Cpu)
                .is_err()
        );

        let mut reordered = ResidentMutationProgramResult::completed(
            program.execution,
            vec![intent.clone()],
            valid_receipts(&request),
        );
        reordered.receipts.swap(rhs_receipt, effect_receipt);
        assert!(
            reordered
                .validate_for_publication(&request, BackendKind::Cpu)
                .is_err()
        );

        let mut forged_provenance = ResidentMutationProgramResult::completed(
            program.execution,
            vec![intent.clone()],
            valid_receipts(&request),
        );
        forged_provenance.receipts[effect_receipt].completion = ResidentDeviceCompletion::Metal;
        assert!(
            forged_provenance
                .validate_for_publication(&request, BackendKind::Cpu)
                .is_err()
        );

        let mut missing = ResidentMutationProgramResult::completed(
            program.execution,
            vec![intent],
            valid_receipts(&request),
        );
        missing.receipts.remove(effect_receipt);
        assert!(
            missing
                .validate_for_publication(&request, BackendKind::Cpu)
                .is_err()
        );
        Ok(())
    }

    #[test]
    fn publication_rejects_effectful_remove_of_unknown_property_token() -> crate::Result<()> {
        let mut request = receipted_request();
        let program = request.mutation.as_mut().expect("mutation program");
        program.property_names = vec!["missing".to_owned()];
        program.property_tokens = vec![None];
        program.label_names.clear();
        program.label_tokens.clear();
        program.commands[0].operation = ResidentMutationOperation::RemoveProperty {
            target: ResidentEntityBinding::Node(ResidentNodeBinding::Start),
            property_name: 0,
        };
        request.validate_mutation()?;
        let program = request.mutation.as_ref().expect("mutation program");
        let intent = ResidentMutationIntent {
            source_row: 0,
            command: 0,
            target_kind: EntityKind::Node,
            target_id: 41,
            action: ResidentMutationIntentAction::RemoveProperty { property_name: 0 },
            effectful: true,
        };
        let result = ResidentMutationProgramResult::completed(
            program.execution,
            vec![intent],
            valid_receipts(&request),
        );
        let error = result
            .validate_for_publication(&request, BackendKind::Cpu)
            .expect_err("unknown property removal effect must be rejected");
        assert_eq!(error.code, ErrorCode::CorruptStorage);
        Ok(())
    }

