    #[test]
    fn exact_ordered_match_create_star_create_profile_rejects_request_corruption() -> Result<()> {
        let body = exact_ordered_match_create_star_create_body()?;
        body.validate(&[])?;

        let mut read_own_writes = body.clone();
        read_own_writes.commands[0] =
            ResidentRowBoundRelationshipCommand::MatchNodeIncludingWrites {
                properties: Vec::new(),
            };
        assert!(read_own_writes.validate_program().is_err());

        let mut unused_label_domain = body.clone();
        unused_label_domain.program.label_names.push("X".to_owned());
        unused_label_domain.program.label_tokens.push(None);
        assert!(unused_label_domain.validate_program().is_err());

        let mut output = body.clone();
        output
            .outputs
            .push(ResidentRowBoundRelationshipOutput::CountRows {
                name: "rows".to_owned(),
            });
        assert!(output.validate_program().is_err());

        let mut candidate_limit = body.clone();
        candidate_limit.command_candidate_limits[2] = 2;
        assert!(candidate_limit.validate_program().is_err());

        let mut oversized_match_domain = body.clone();
        oversized_match_domain.command_candidate_limits[0] = 3;
        assert!(oversized_match_domain.validate_program().is_err());

        let mut schedule = body.clone();
        schedule.schedule.stages.swap(1, 2);
        assert!(schedule.validate_program().is_err());

        assert!(
            body.validate(&[ResidentRowMutationInputMap {
                entries: Vec::new(),
            }])
            .is_err()
        );
        Ok(())
    }

