    #[test]
    fn exact_ordered_read_own_writes_match_profile_is_distinct_and_bounded() -> Result<()> {
        let body = exact_ordered_match_create_star_match_create_body()?;
        body.validate(&[])?;
        assert_eq!(body.command_candidate_limits, [2, 1, 4, 1]);
        assert_eq!(body.capacities.maximum_rows, 8);
        assert_eq!(body.capacities.maximum_intents, 10);
        assert_eq!(body.capacities.maximum_node_lineage_entries, 10);

        let mut immutable_second_match = body.clone();
        immutable_second_match.commands[2] = ResidentRowBoundRelationshipCommand::MatchNode {
            properties: Vec::new(),
        };
        assert!(immutable_second_match.validate_program().is_err());

        let mut post_write_first_match = body.clone();
        post_write_first_match.commands[0] =
            ResidentRowBoundRelationshipCommand::MatchNodeIncludingWrites {
                properties: Vec::new(),
            };
        assert!(post_write_first_match.validate_program().is_err());

        for forged_limit in [3, 5] {
            let mut candidate_limit = body.clone();
            candidate_limit.command_candidate_limits[2] = forged_limit;
            assert!(candidate_limit.validate_program().is_err());
        }

        let mut labelled = body.clone();
        labelled.program.label_names.push("X".to_owned());
        labelled.program.label_tokens.push(None);
        let ResidentRowCreateCommand::MatchNode(second_match) = &mut labelled.program.commands[2]
        else {
            unreachable!()
        };
        second_match.labels.push(0);
        assert!(labelled.validate_program().is_err());

        let mut reordered = body.clone();
        reordered.schedule.stages.swap(1, 2);
        assert!(reordered.validate_program().is_err());
        assert!(
            body.validate(&[ResidentRowMutationInputMap {
                entries: Vec::new(),
            }])
            .is_err()
        );
        Ok(())
    }

