    #[test]
    fn create3_11_graph_free_relationship_create_profile_is_exact_and_fail_closed() -> Result<()> {
        let body = exact_create3_11_graph_free_relationship_create_body()?;
        assert!(body.exact_create3_11_graph_free_relationship_create_profile());
        body.validate(&[])?;

        let mut semantics = body.clone();
        semantics.commands[1] = ResidentRowBoundRelationshipCommand::CreateNode;
        assert!(!semantics.exact_create3_11_graph_free_relationship_create_profile());
        assert!(semantics.exact_graph_free_create_profile());
        semantics.validate_program()?;

        let mut invalid_semantics = body.clone();
        invalid_semantics.commands[1] = ResidentRowBoundRelationshipCommand::CreateRelationship;
        assert!(invalid_semantics.validate_program().is_err());

        let mut structural_order = body.clone();
        structural_order.program.commands.swap(1, 2);
        assert!(structural_order.validate_program().is_err());

        let mut candidate_limit = body.clone();
        candidate_limit.command_candidate_limits[1] = 2;
        assert!(candidate_limit.validate_program().is_err());

        let mut source_endpoint = body.clone();
        let ResidentRowCreateCommand::CreateRelationship(relationship) =
            &mut source_endpoint.program.commands[3]
        else {
            panic!("Create3 [11] relationship command changed shape")
        };
        relationship.source_entity = 1;
        assert!(source_endpoint.validate_program().is_err());

        let mut reversed_endpoints = body.clone();
        let ResidentRowCreateCommand::CreateRelationship(relationship) =
            &mut reversed_endpoints.program.commands[3]
        else {
            panic!("Create3 [11] relationship command changed shape")
        };
        relationship.source_entity = 0;
        relationship.target_entity = 2;
        assert!(reversed_endpoints.validate_program().is_err());

        let mut relationship_type = body.clone();
        relationship_type.program.relationship_type_names[0] = "R".to_owned();
        assert!(relationship_type.validate_program().is_err());

        let mut property_domain = body.clone();
        property_domain.program.property_names.push("p".to_owned());
        property_domain.program.property_tokens.push(None);
        assert!(property_domain.validate_program().is_err());

        let mut label_domain = body.clone();
        label_domain.program.label_names.push("L".to_owned());
        label_domain.program.label_tokens.push(None);
        assert!(label_domain.validate_program().is_err());

        let mut output = body.clone();
        output
            .outputs
            .push(ResidentRowBoundRelationshipOutput::CountRows {
                name: "rows".to_owned(),
            });
        assert!(output.validate_program().is_err());

        let mut value_slots = body.clone();
        value_slots.schedule.value_slot_count = 1;
        assert!(value_slots.validate_program().is_err());

        let mut schedule = body.clone();
        schedule.schedule.stages.swap(1, 2);
        assert!(schedule.validate_program().is_err());

        let mut entity_slots = body.clone();
        entity_slots.program.entity_slot_count = 5;
        assert!(entity_slots.validate_program().is_err());

        assert!(
            body.validate(&[ResidentRowMutationInputMap {
                entries: Vec::new(),
            }])
            .is_err()
        );
        Ok(())
    }

