    #[test]
    fn one_or_two_relationship_merges_seal_local_capacity_and_explicit_path_slot() -> Result<()> {
        let (one_program, one_commands) = fixture(1);
        let one_outputs = vec![ResidentRowBoundRelationshipOutput::Path {
            name: "p".to_owned(),
            start_entity: 0,
            relationship_entity: 2,
            end_entity: 1,
        }];
        let one = ResidentRowBoundRelationshipCapacities::derive(
            &one_program,
            &one_commands,
            &one_outputs,
            &[],
            0,
            0,
        )?;
        assert_eq!(one.maximum_statement_local_relationships, 1);

        let (program, commands) = fixture(2);
        let outputs = vec![ResidentRowBoundRelationshipOutput::Path {
            name: "p".to_owned(),
            start_entity: 0,
            relationship_entity: 3,
            end_entity: 1,
        }];
        let capacities = ResidentRowBoundRelationshipCapacities::derive(
            &program,
            &commands,
            &outputs,
            &[],
            0,
            0,
        )?;
        assert_eq!(capacities.maximum_statement_local_relationships, 2);
        assert!(capacities.scratch_bytes > one.scratch_bytes);
        ResidentRowBoundRelationshipMergeBody {
            program: program.clone(),
            commands: commands.clone(),
            command_candidate_limits: vec![1; commands.len()],
            schedule: ResidentRowBoundRelationshipSchedule::identity(program.commands.len())?,
            merge_property_sets: Vec::new(),
            merge_label_sets: Vec::new(),
            outputs: outputs.clone(),
            capacities,
        }
        .validate(&[])?;

        let mut wrong_slot = outputs;
        let ResidentRowBoundRelationshipOutput::Path {
            relationship_entity,
            ..
        } = &mut wrong_slot[0]
        else {
            unreachable!()
        };
        *relationship_entity = 0;
        assert!(
            ResidentRowBoundRelationshipCapacities::derive(
                &program,
                &commands,
                &wrong_slot,
                &[],
                0,
                0,
            )
            .is_err()
        );
        Ok(())
    }

